import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';
import { useGlobalAudioContext } from '../contexts/GlobalAudioContext';
import vzbuQ from '../assets/vzbuQ.jpg';

interface ScarewareCollectionProps {
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape';
  onAdvancePhase: (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => void;
  onNortonStateChange?: (escalation: boolean, muted: boolean) => void; // NEW: Norton state callback
}

// Educational popup component for fake button clicks
const EducationalPopup: React.FC<{ onClose: () => void }> = ({ onClose }) => (
  <div className="safe-zone" style={{
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    background: 'rgba(0,0,0,0.8)',
    zIndex: 30000,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center'
  }}>
    <div style={{
      background: 'white',
      padding: '2rem',
      borderRadius: '12px',
      maxWidth: '500px',
      textAlign: 'center',
      boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
      position: 'relative'
    }}>
      {/* Close button */}
      <button
        onClick={onClose}
        style={{
          position: 'absolute',
          top: '0.5rem',
          right: '0.5rem',
          background: 'none',
          border: 'none',
          fontSize: '1.5rem',
          cursor: 'pointer',
          color: '#666',
          padding: '0.25rem',
          borderRadius: '50%',
          width: '2rem',
          height: '2rem',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          transition: 'background-color 0.2s'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.backgroundColor = '#f0f0f0';
          e.currentTarget.style.color = '#333';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.backgroundColor = 'transparent';
          e.currentTarget.style.color = '#666';
        }}
      >
        ×
      </button>

      <h3 style={{ color: '#dc3545', marginBottom: '1rem' }}>⚠️ Educational Moment!</h3>
      <p style={{ fontSize: '1.1rem', marginBottom: '1.5rem' }}>
        <strong>Never click anywhere on scareware pages!</strong>
        <br />
        Real scareware can make the entire page clickable to trap you or download malware. 
        <br />
        Even clicking outside of buttons can be dangerous in these situations.
      </p>
    </div>
  </div>
);

const ScarewareCollection: React.FC<ScarewareCollectionProps> = ({ 
  currentPhase, 
  onAdvancePhase, 
  onNortonStateChange
}) => {
  const { startSpeech, stopSpeech } = useGlobalAudioContext();
  const startSpeechRef = React.useRef(startSpeech);
  const stopSpeechRef = React.useRef(stopSpeech);

  // Update refs when functions change
  React.useEffect(() => {
    startSpeechRef.current = startSpeech;
    stopSpeechRef.current = stopSpeech;
  }, [startSpeech, stopSpeech]);
  const [showContent, setShowContent] = useState(false);
  const [threatLevel, setThreatLevel] = useState(0);
  const [showEducationalPopup, setShowEducationalPopup] = useState(false);
  // Countdown timer state (10 minutes) - for Microsoft phase
  const [countdown, setCountdown] = useState(600);
  useEffect(() => {
    if (countdown <= 0) {
      setCountdown(600); // Reset to 10:00
      return;
    }
    const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
    return () => clearTimeout(timer);
  }, [countdown]);
  const minutes = Math.floor(countdown / 60).toString().padStart(2, '0');
  const seconds = (countdown % 60).toString().padStart(2, '0');

  // Use real scareware browser hijacking techniques for all scareware phases
  // Only start hijacking after content is actually visible
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: false, // Disable global fullscreen - we'll handle it per overlay
    preventEscape: showContent,
    preventTabSwitch: showContent,
    preventMouseEvents: showContent,
    preventWindowControl: showContent,
    delayStart: 2000 // 2 second delay after content is visible
  });

  // Add targeted fullscreen hijacking to scareware overlays
  React.useEffect(() => {
    if (!showContent) return;

    const handleScarewareClick = (e: Event) => {
      const target = e.target as Element;

      // Trigger fullscreen for any click within scareware overlays
      // (but not on simulation controls or educational popup which are protected)
      if (!target.closest('.simulation-controls') && !target.closest('.safe-zone')) {
        // Trigger fullscreen using the same logic as the hijacking hook
        try {
          if (!document.fullscreenElement && 
              !(document as any).webkitFullscreenElement && 
              !(document as any).mozFullScreenElement && 
              !(document as any).msFullscreenElement) {

            if ((document.documentElement as any).requestFullScreen) {
              (document.documentElement as any).requestFullScreen();
            } else if ((document.documentElement as any).mozRequestFullScreen) {
              (document.documentElement as any).mozRequestFullScreen();
            } else if ((document.documentElement as any).webkitRequestFullScreen) {
              (document.documentElement as any).webkitRequestFullScreen((Element as any).ALLOW_KEYBOARD_INPUT);
            } else if ((document.documentElement as any).msRequestFullscreen) {
              (document.documentElement as any).msRequestFullscreen();
            }
          }
        } catch (error) {
          // Silently handle fullscreen errors
        }
      }
    };

    // Function to add listeners to scareware overlays
    const addListeners = () => {
      const overlays = document.querySelectorAll('.scareware-overlay, .browser-hijacking-overlay, .fullscreen-overlay');

      overlays.forEach((overlay) => {
        overlay.addEventListener('click', handleScarewareClick, true);
        overlay.addEventListener('mousedown', handleScarewareClick, true);
      });
    };

    // Function to remove listeners
    const removeListeners = () => {
      const overlays = document.querySelectorAll('.scareware-overlay, .browser-hijacking-overlay, .fullscreen-overlay');
      overlays.forEach((overlay) => {
        overlay.removeEventListener('click', handleScarewareClick, true);
        overlay.removeEventListener('mousedown', handleScarewareClick, true);
      });
    };

    // Initial setup
    addListeners();

    // Re-add listeners when educational popup closes (to ensure they're still active)
    const checkAndReaddListeners = () => {
      if (!showEducationalPopup) {
        setTimeout(addListeners, 100); // Small delay to ensure DOM is ready
      }
    };

    // Check periodically to ensure listeners are still active
    const interval = setInterval(checkAndReaddListeners, 2000);

    return () => {
      clearInterval(interval);
      removeListeners();
    };
  }, [showContent, showEducationalPopup]);

  useEffect(() => {
    // Show content immediately
    setShowContent(true);

    // Escalate threat level over time
    const threatTimer = setInterval(() => {
      setThreatLevel(prev => {
        if (prev < 10) return prev + 1;
        clearInterval(threatTimer);
        return prev;
      });
    }, 2000);

    return () => {
      clearInterval(threatTimer);
    };
  }, []);

  const handleContinue = () => {
    const phases = ['norton', 'microsoft', 'google', 'malwarebytes', 'generic', 'advanced', 'extreme'];
    const currentIndex = phases.indexOf(currentPhase);
    if (currentIndex < phases.length - 1) {
      onAdvancePhase(phases[currentIndex + 1] as any);
    }
  };



  const handleFakeButtonClick = () => {
    setShowEducationalPopup(true);
  };

  const handleEducationalPopupClose = () => {
    setShowEducationalPopup(false);
  };

  // For the Norton countdown timer
  const [nortonTimer, setNortonTimer] = useState(179); // 2:59 in seconds
  const [nortonEscalation, setNortonEscalation] = useState(false);
  const [fakeThreats, setFakeThreats] = useState(23);

  // Store interval references for cleanup
  const threatIntervalRef = React.useRef<NodeJS.Timeout | null>(null);
  const resetTimeoutRef = React.useRef<NodeJS.Timeout | null>(null);

  const fakeThreatsRef = React.useRef(fakeThreats);
  const nortonEscalationRef = React.useRef(nortonEscalation);

  // Update refs when values change
  React.useEffect(() => {
    fakeThreatsRef.current = fakeThreats;
    nortonEscalationRef.current = nortonEscalation;
  }, [fakeThreats, nortonEscalation]);

  // Notify parent of Norton state changes
  React.useEffect(() => {
    if (onNortonStateChange) {
      onNortonStateChange(nortonEscalation, false); // Always pass false for muted since we removed speech
    }
  }, [nortonEscalation, onNortonStateChange]);

  // Cleanup when phase changes or component unmounts
  React.useEffect(() => {
    return () => {
      // Clear any threat intervals
      if (threatIntervalRef.current) {
        clearInterval(threatIntervalRef.current);
        threatIntervalRef.current = null;
      }

      // Clear any reset timeouts
      if (resetTimeoutRef.current) {
        clearTimeout(resetTimeoutRef.current);
        resetTimeoutRef.current = null;
      }
    };
  }, [currentPhase]); // Trigger cleanup when phase changes

  // Handle speech transitions for all scareware phases (immediate transitions)
  React.useEffect(() => {
    if (showContent) {
      console.log(`🎵 Speech transition: ${currentPhase} (escalation: ${nortonEscalationRef.current})`);
      // Immediately start appropriate speech for current phase
      switch (currentPhase) {
        case 'norton':
          const mode = nortonEscalationRef.current ? 'escalation' : 'normal';
          console.log(`🎵 Starting Norton speech: ${mode} mode`);
          startSpeechRef.current('norton', mode);
          break;
        case 'microsoft':
          console.log('🎵 Starting Microsoft speech');
          startSpeechRef.current('microsoft', 'normal');
          break;
        case 'google':
          console.log('🎵 Starting Google speech');
          startSpeechRef.current('google', 'normal');
          break;
        case 'malwarebytes':
          console.log('🎵 Starting Malwarebytes speech');
          startSpeechRef.current('malwarebytes', 'normal');
          break;
        case 'generic':
          console.log('🎵 Starting Generic speech');
          startSpeechRef.current('generic', 'normal');
          break;
        case 'advanced':
          console.log('🎵 Starting Advanced speech');
          startSpeechRef.current('advanced', 'normal');
          break;
        case 'extreme':
          console.log('🎵 Starting Extreme speech');
          startSpeechRef.current('extreme', 'normal');
          break;
        case 'escape':
          console.log(`🎵 Stopping speech for phase: ${currentPhase} (no speech configured)`);
          // Stop speech for escape phase
          stopSpeechRef.current();
          break;
      }
    }
  }, [currentPhase, showContent]); // Removed nortonEscalation from dependencies







  // Global functions for Norton phase debugging
  React.useEffect(() => {
    if (currentPhase === 'norton') {
      // Toggle between escalation and normal state
      (window as any).toggleNortonEscalation = () => {
        if (nortonEscalationRef.current) {
          // Return to normal state

          // Clear any running intervals and timeouts
          if (threatIntervalRef.current) {
            clearInterval(threatIntervalRef.current);
            threatIntervalRef.current = null;
          }
          if (resetTimeoutRef.current) {
            clearTimeout(resetTimeoutRef.current);
            resetTimeoutRef.current = null;
          }
          // Clear any running intervals and timeouts

          setNortonEscalation(false);
          setNortonTimer(179);
          setFakeThreats(23);
        } else {
          // Go to escalation state
          setNortonTimer(0);
          setNortonEscalation(true);
          setFakeThreats(23);

          // Start the threat increase interval immediately
          threatIntervalRef.current = setInterval(() => {
            setFakeThreats(t => {
              const newThreats = t + Math.floor(Math.random() * 5) + 1;
              return newThreats;
            });
          }, 500);

          // Reset after 2 minutes (120 seconds)
          resetTimeoutRef.current = setTimeout(() => {
            if (threatIntervalRef.current) {
              clearInterval(threatIntervalRef.current);
              threatIntervalRef.current = null;
            }
            setNortonTimer(179);
            setNortonEscalation(false);
            setFakeThreats(23);
          }, 120000);
        }
      };



      return () => {
        delete (window as any).toggleNortonEscalation;
      };
    }
  }, [currentPhase]); // Removed nortonEscalation from dependencies

  useEffect(() => {
    if (currentPhase === 'norton') {
      if (nortonTimer > 0) {
        const interval = setInterval(() => setNortonTimer(t => t - 1), 1000);
        return () => clearInterval(interval);
      } else if (!nortonEscalationRef.current) {
        // Start escalation when timer hits 0
        setNortonEscalation(true);
        // Rapidly increase fake threats
        threatIntervalRef.current = setInterval(() => {
          setFakeThreats(t => {
            const newThreats = t + Math.floor(Math.random() * 5) + 1;
            return newThreats;
          });
        }, 500);

        // Reset after 2 minutes (120 seconds)
        resetTimeoutRef.current = setTimeout(() => {
          if (threatIntervalRef.current) {
            clearInterval(threatIntervalRef.current);
            threatIntervalRef.current = null;
          }
          setNortonTimer(179);
          setNortonEscalation(false);
          setFakeThreats(23);
        }, 120000);

        return () => {
          if (threatIntervalRef.current) {
            clearInterval(threatIntervalRef.current);
            threatIntervalRef.current = null;
          }
          if (resetTimeoutRef.current) {
            clearTimeout(resetTimeoutRef.current);
            resetTimeoutRef.current = null;
          }
        };
      }
    }
  }, [currentPhase, nortonTimer]); // Removed nortonEscalation from dependencies

  const timerMinutes = String(Math.floor(nortonTimer / 60)).padStart(2, '0');
  const timerSeconds = String(nortonTimer % 60).padStart(2, '0');

  // Microsoft phishing flow state and helpers
  const [step, setStep] = useState<'verify' | 'email' | 'password'>('verify');
  const [email, setEmail] = useState('');
  const [emailInput, setEmailInput] = useState('');
  const [emailError, setEmailError] = useState('');
  const [password, setPassword] = useState('');
  const [boxAnimating, setBoxAnimating] = useState(false);
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const handleAdvanceStep = (nextStep: 'verify' | 'email' | 'password') => {
    setBoxAnimating(true);
    setTimeout(() => {
      setBoxAnimating(false);
      setStep(nextStep);
    }, 350);
  };
  const renderVerifyBox = () => (
    <div className={`ms-phish-box${boxAnimating ? ' slide-left' : ''}`}>
      {/* ...existing Microsoft info box content, but Confirm Identity button triggers handleAdvanceStep('email')... */}
      <div style={{ textAlign: 'right' }}>
        <button
          style={{
            background: '#0067c5',
            color: 'white',
            border: '1px solid #222',
            borderRadius: 3,
            padding: '12px 38px',
            fontSize: 18,
            fontWeight: 400,
            cursor: 'pointer',
            boxShadow: '0 2px 4px rgba(0,0,0,0.10)',
            outline: 'none',
            transition: 'background 0.2s',
          }}
          onClick={() => handleAdvanceStep('email')}
        >
          Confirm Identity
        </button>
      </div>
    </div>
  );
  const renderEmailBox = () => (
    <div className={`ms-phish-box${boxAnimating ? ' slide-left' : ''}`}>
      <img
        src="https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Microsoft_logo_%282012%29.svg/512px-Microsoft_logo_%282012%29.svg.png"
        alt="Microsoft"
        style={{ width: 140, marginBottom: 32, display: 'block' }}
      />
      <h2 style={{ fontWeight: 400, fontSize: 28, margin: 0, marginBottom: 24 }}>
        Sign in
      </h2>
      <div style={{ fontSize: 17, marginBottom: 18 }}>
        Enter your email address to continue.
      </div>
      <input
        type="email"
        value={emailInput}
        onChange={e => setEmailInput(e.target.value)}
        placeholder="Email address"
        style={{
          width: '100%',
          padding: '12px',
          fontSize: 17,
          border: '1px solid #bbb',
          borderRadius: 4,
          marginBottom: 10
        }}
        autoFocus
      />
      {emailError && <div style={{ color: '#b71c1c', fontSize: 15, marginBottom: 10 }}>{emailError}</div>}
      <div style={{ textAlign: 'right' }}>
        <button
          style={{
            background: '#0067c5',
            color: 'white',
            border: '1px solid #222',
            borderRadius: 3,
            padding: '10px 32px',
            fontSize: 17,
            fontWeight: 400,
            cursor: 'pointer',
            boxShadow: '0 2px 4px rgba(0,0,0,0.10)',
            outline: 'none',
            transition: 'background 0.2s',
          }}
          onClick={() => {
            if (!emailRegex.test(emailInput)) {
              setEmailError('Please enter a valid email address.');
              return;
            }
            setEmail(emailInput);
            setEmailError('');
            handleAdvanceStep('password');
          }}
        >
          Next
        </button>
      </div>
    </div>
  );
  const renderPasswordBox = () => (
    <div className={`ms-phish-box${boxAnimating ? ' slide-left' : ''}`}>
      <img
        src="https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Microsoft_logo_%282012%29.svg/512px-Microsoft_logo_%282012%29.svg.png"
        alt="Microsoft"
        style={{ width: 140, marginBottom: 32, display: 'block' }}
      />
      <div style={{ color: '#222', fontSize: 17, marginBottom: 8 }}>{email}</div>
      <h2 style={{ fontWeight: 400, fontSize: 24, margin: 0, marginBottom: 18 }}>
        Enter password
      </h2>
      <div style={{ fontSize: 16, marginBottom: 18 }}>
        Because you're accessing sensitive info, you need to verify your password.
      </div>
      <input
        type="password"
        value={password}
        onChange={e => setPassword(e.target.value)}
        placeholder="Password"
        style={{
          width: '100%',
          padding: '12px',
          fontSize: 17,
          border: '1px solid #bbb',
          borderRadius: 4,
          marginBottom: 10
        }}
        autoFocus
      />
      <div style={{ marginBottom: 18 }}>
        <a href="#" style={{ color: '#0067c5', fontSize: 15, textDecoration: 'underline' }}>Forgot my password</a>
      </div>
      <div style={{ textAlign: 'right' }}>
        <button
          style={{
            background: '#0067c5',
            color: 'white',
            border: '1px solid #222',
            borderRadius: 3,
            padding: '10px 32px',
            fontSize: 17,
            fontWeight: 400,
            cursor: 'pointer',
            boxShadow: '0 2px 4px rgba(0,0,0,0.10)',
            outline: 'none',
            transition: 'background 0.2s',
          }}
          onClick={() => { /* You can add a fake submit handler here */ }}
        >
          Sign in
        </button>
      </div>
    </div>
  );

  if (!showContent) {
    return null;
  }

  // Show educational popup if triggered
  if (showEducationalPopup) {
    return (
      <EducationalPopup 
        onClose={handleEducationalPopupClose}
      />
    );
  }



  // Escape phase - no browser hijacking
  if (currentPhase === 'escape') {
    return (
      <div className="simulation-content safe-zone" style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(135deg, #28a745, #20c997, #28a745)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        textAlign: 'center'
      }}>
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          <h1 style={{ 
            fontSize: '3rem', 
            marginBottom: '2rem', 
            textShadow: '2px 2px 4px rgba(0,0,0,0.8)'
          }}>
            🛡️ How to Escape Real Scareware
          </h1>

          <div style={{ fontSize: '1.3rem', marginBottom: '2rem' }}>
            <strong>If you encounter real scareware:</strong>
          </div>

          <div style={{ fontSize: '1.1rem', marginBottom: '2rem', textAlign: 'left' }}>
            <ol style={{ marginLeft: '2rem' }}>
              <li><strong>Don't panic!</strong> Stay calm and don't click any buttons</li>
              <li><strong>Force close the browser</strong> using Ctrl+Alt+Delete (Windows) or Cmd+Option+Esc (Mac)</li>
              <li><strong>Restart your computer</strong> to clear any temporary files</li>
              <li><strong>Run a legitimate antivirus scan</strong> with software you trust</li>
              <li><strong>Never pay ransom</strong> - it doesn't guarantee recovery</li>
              <li><strong>Report the incident</strong> to authorities if needed</li>
            </ol>
          </div>

          <div style={{ marginTop: '2rem' }}>
            <button 
              className="button button-primary" 
              onClick={() => onAdvancePhase('norton')}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem', 
                marginRight: '1rem',
                background: '#007bff',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)',
                fontWeight: 'bold'
              }}
            >
              Restart Simulation
            </button>

          </div>
        </div>
      </div>
    );
  }

  // Norton Antivirus Scareware
  if (currentPhase === 'norton') {
    return (
      <>
        {/* Flashing button keyframes */}
        <style>{`
          @keyframes norton-flash {
            0% { box-shadow: 0 0 0 0 #fdb51188; background: #fdb511; }
            50% { box-shadow: 0 0 24px 8px #fdb511cc; background: #fffbe6; }
            100% { box-shadow: 0 0 0 0 #fdb51188; background: #fdb511; }
          }
          @keyframes norton-escalation {
            0% { box-shadow: 0 0 0 0 #dc354588; background: #dc3545; transform: scale(1); }
            25% { box-shadow: 0 0 32px 12px #dc3545ff; background: #ff6b6b; transform: scale(1.05); }
            50% { box-shadow: 0 0 0 0 #dc354588; background: #dc3545; transform: scale(1); }
            75% { box-shadow: 0 0 32px 12px #dc3545ff; background: #ff6b6b; transform: scale(1.05); }
            100% { box-shadow: 0 0 0 0 #dc354588; background: #dc3545; transform: scale(1); }
          }
          @keyframes pulse-warning {
            0% { transform: scale(1); filter: drop-shadow(0 0 0 #fdb511); }
            50% { transform: scale(1.15); filter: drop-shadow(0 0 8px #fdb511); }
            100% { transform: scale(1); filter: drop-shadow(0 0 0 #fdb511); }
          }
          @keyframes pulse-danger {
            0% { transform: scale(1); filter: drop-shadow(0 0 0 #dc3545); }
            50% { transform: scale(1.2); filter: drop-shadow(0 0 12px #dc3545); }
            100% { transform: scale(1); filter: drop-shadow(0 0 0 #dc3545); }
          }
        `}</style>
        <div className="scareware-overlay" style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'white',
          zIndex: 10000,
          display: 'flex',
          flexDirection: 'column',
          color: '#000000',
